cat > /app/hierarchical_model.stan <<'EOF'
// Hierarchical Bayesian binomial-Beta model
// y_i ~ Binomial(n_i, theta_i)
// theta_i ~ Beta(alpha, beta)
// p(alpha, beta) prop (alpha + beta)^(-5/2)  (improper prior)

data {
  int<lower=1> N;              // number of groups
  array[N] int<lower=0> y;     // successes
  array[N] int<lower=1> n;     // trials
}

parameters {
  vector<lower=0>[N] theta;    // group-level probabilities
  lower=0
  lower=0
}

transformed parameters {
  real mu;      // group-level mean probability
  real kappa;   // group-level concentration (alpha + beta)
  lower=0
  lower=0
}

model {
  // Hyperprior: (alpha, beta) prop (alpha + beta)^(-5/2)
  kappa ~ exp(-2.5 * log(kappa));

  // Likelihood
  for (i in 1:N)
    y[i] ~ binomial(n[i], theta[i]);
}
EOF
echo done

